PRAGMA foreign_keys = ON;

CREATE TABLE knowledge_documents (
  id TEXT PRIMARY KEY NOT NULL CHECK (length(trim(id)) > 0),
  title TEXT NOT NULL CHECK (length(trim(title)) > 0),
  tags TEXT NOT NULL CHECK (json_valid(tags) AND json_type(tags) = 'array' AND json_array_length(tags) > 0),
  content TEXT NOT NULL CHECK (length(trim(content)) > 0),
  sources TEXT NOT NULL CHECK (json_valid(sources) AND json_type(sources) = 'array' AND json_array_length(sources) > 0),
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published')),
  created_at TEXT NOT NULL CHECK (length(created_at) = 24),
  updated_at TEXT NOT NULL CHECK (length(updated_at) = 24)
);

CREATE INDEX knowledge_documents_status_updated_idx ON knowledge_documents(status, updated_at DESC);

INSERT OR IGNORE INTO knowledge_documents (id, title, tags, content, sources, status, created_at, updated_at) VALUES ('kb-no-power-sequence', 'Secuencia de diagnóstico: equipo que no enciende', '["no-power","power-sequence","input-power","standby-rails"]', 'Separar primero ausencia total de encendido de un equipo que enciende sin imagen. Confirmar cargador, conector y tensión de entrada; luego verificar que la tensión atraviese la etapa de MOSFET de entrada. Con alimentación desconectada, revisar resistencia a tierra antes de energizar. Si la entrada es correcta, buscar 3VALW/5VALW y sus señales de habilitación. Después comprobar botón de encendido, EC, BIOS y secuencia de fuentes secundarias. Registrar cada valor; una fuente ausente orienta el próximo paso, pero no confirma por sí sola el componente defectuoso.', '["Referencia técnica interna; confirmar con el manual de servicio y esquema específicos de la placa"]', 'published', '2026-08-12T00:00:00.000Z', '2026-08-12T00:00:00.000Z');
INSERT OR IGNORE INTO knowledge_documents (id, title, tags, content, sources, status, created_at, updated_at) VALUES ('kb-input-power-stage', 'Etapa de alimentación de entrada', '["input-power","adapter","dc-jack","input-mosfet","charger-ic"]', 'Medir tensión del adaptador sin carga y conectada. Inspeccionar jack, fusible y ambos lados de los MOSFET de entrada. Comparar gate, source y drain respecto de tierra, identificando antes si son canal N o P. Verificar alimentación y señales de detección del controlador de carga según el esquema de la placa. Si la tensión no atraviesa la etapa, no asumir MOSFET dañado: un corto posterior, protección activa o ausencia de habilitación también pueden bloquearla.', '["Referencia técnica interna; confirmar con el manual de servicio y esquema específicos de la placa"]', 'published', '2026-08-12T00:00:00.000Z', '2026-08-12T00:00:00.000Z');
INSERT OR IGNORE INTO knowledge_documents (id, title, tags, content, sources, status, created_at, updated_at) VALUES ('kb-standby-rails', 'Fuentes de espera 3VALW y 5VALW', '["standby-rails","3valw","5valw","enable","no-power"]', '3VALW y 5VALW suelen ser fuentes de espera necesarias al inicio de la secuencia, aunque la arquitectura varía por placa. Medir entrada del convertidor, resistencia a tierra de cada salida, tensión en bobinas y señal de enable. Distinguir una salida ausente de una salida que intenta arrancar y cae. Si una fuente está presente y la otra no, comparar resistencias, MOSFETs, bobinas y habilitaciones del canal afectado. Confirmar siempre nombres y valores con boardview o esquema específico cuando esté disponible.', '["Referencia técnica interna; confirmar con el manual de servicio y esquema específicos de la placa"]', 'published', '2026-08-12T00:00:00.000Z', '2026-08-12T00:00:00.000Z');
INSERT OR IGNORE INTO knowledge_documents (id, title, tags, content, sources, status, created_at, updated_at) VALUES ('kb-buck-converters', 'Convertidores buck en placas de laptop', '["buck-converter","pwm","mosfet","inductor","power-rail"]', 'En un buck, comprobar tensión de entrada, enable, alimentación del controlador, conmutación y salida en la bobina. Una salida nula puede deberse a falta de entrada o habilitación, protección por sobrecorriente, corto en la carga o falla del propio convertidor. Con el equipo apagado, comparar resistencia a tierra; energizado, observar si hay pulsos o intentos de arranque. No puentear protecciones ni reemplazar componentes sólo por una medición aislada.', '["Referencia técnica interna; confirmar con el manual de servicio y esquema específicos de la placa"]', 'published', '2026-08-12T00:00:00.000Z', '2026-08-12T00:00:00.000Z');
INSERT OR IGNORE INTO knowledge_documents (id, title, tags, content, sources, status, created_at, updated_at) VALUES ('kb-short-to-ground', 'Búsqueda de cortocircuitos a tierra', '["short-to-ground","low-resistance","power-rail","current-injection"]', 'Desconectar cargador y batería antes de medir resistencia a tierra. Una resistencia baja no siempre es un corto: fuentes de núcleo y GPU pueden ser naturalmente bajas. Comparar con la función de la línea, el esquema y placas conocidas. Para inyección, aislar la fuente cuando corresponda, usar tensión menor o igual a la nominal y limitar corriente desde el inicio. Buscar calentamiento de forma controlada. No inyectar en líneas desconocidas, datos, BIOS o señales sensibles.', '["Referencia técnica interna; confirmar con el manual de servicio y esquema específicos de la placa"]', 'published', '2026-08-12T00:00:00.000Z', '2026-08-12T00:00:00.000Z');
INSERT OR IGNORE INTO knowledge_documents (id, title, tags, content, sources, status, created_at, updated_at) VALUES ('kb-battery-charging', 'Diagnóstico básico del circuito de carga', '["battery-charging","battery","adapter","charger-ic"]', 'Separar tres casos: equipo funciona con adaptador pero no carga, funciona sólo con batería o no reconoce una de las fuentes. Registrar tensión del adaptador, tensión y estado reportado de batería, detección de adaptador y comportamiento con una batería conocida cuando sea seguro. Revisar conector, fusible, MOSFETs, controlador de carga y comunicación de batería según el esquema. Una batería agotada, bloqueada o degradada puede imitar una falla de placa; una lectura de software sola no confirma la causa.', '["Referencia técnica interna; confirmar con el manual de servicio y esquema específicos de la placa"]', 'published', '2026-08-12T00:00:00.000Z', '2026-08-12T00:00:00.000Z');
INSERT OR IGNORE INTO knowledge_documents (id, title, tags, content, sources, status, created_at, updated_at) VALUES ('kb-no-image', 'Equipo enciende pero no muestra imagen', '["no-image","display","backlight","external-display","post"]', 'Confirmar primero señales reales de encendido: consumo, ventilador, LEDs, actividad de almacenamiento o respuesta de teclado. Probar monitor externo y linterna sobre el panel para separar video, panel y retroiluminación. Inspeccionar cable y conector con alimentación desconectada. Si tampoco hay imagen externa, revisar POST, memoria, reset, clocks, BIOS y fuentes de CPU/GPU. No concluir falla de GPU sólo por pantalla negra; documentar qué pruebas producen cambios.', '["Referencia técnica interna; confirmar con el manual de servicio y esquema específicos de la placa"]', 'published', '2026-08-12T00:00:00.000Z', '2026-08-12T00:00:00.000Z');
INSERT OR IGNORE INTO knowledge_documents (id, title, tags, content, sources, status, created_at, updated_at) VALUES ('kb-bios-ec-basics', 'Fundamentos de BIOS y Embedded Controller', '["bios-ec","bios","ec","firmware","spi","power-sequence"]', 'El EC participa en botón de encendido, detección de adaptador/batería y secuencias; la BIOS contiene firmware de arranque. Antes de atribuir la falla al firmware, confirmar alimentaciones de espera, reset, reloj y actividad del bus SPI cuando sea posible. Guardar un respaldo verificado antes de programar y usar una imagen exacta para placa y revisión. Una reprogramación exitosa no demuestra que BIOS fuera la causa. Registrar versión, origen del archivo y resultado de la prueba.', '["Referencia técnica interna; confirmar con el manual de servicio y esquema específicos de la placa"]', 'published', '2026-08-12T00:00:00.000Z', '2026-08-12T00:00:00.000Z');
INSERT OR IGNORE INTO knowledge_documents (id, title, tags, content, sources, status, created_at, updated_at) VALUES ('kb-storage-data-preservation', 'Almacenamiento inestable y preservación de datos', '["storage","data-backup","smart","filesystem","read-errors"]', 'Ante lentitud extrema, errores de lectura, desapariciones o ruidos anómalos, priorizar la copia de datos autorizada antes de pruebas intensivas. Registrar modelo, interfaz, detección en BIOS y sistema, estado SMART y errores observados. Un filesystem dañado puede ser consecuencia y no causa primaria. No ejecutar escrituras, reparaciones repetidas ni pruebas de superficie sobre una unidad con signos físicos de falla antes de acordar el riesgo sobre los datos.', '["Referencia técnica interna; confirmar con el manual de servicio y esquema específicos de la placa"]', 'published', '2026-08-12T00:00:00.000Z', '2026-08-12T00:00:00.000Z');
INSERT OR IGNORE INTO knowledge_documents (id, title, tags, content, sources, status, created_at, updated_at) VALUES ('kb-hdd-mechanical-failure', 'HDD con clics, silbidos o fallas mecánicas', '["hdd","mechanical-noise","clicking","storage","data-backup"]', 'Clics repetitivos, intentos de giro o silbidos acompañados de lentitud y errores de lectura son señales de riesgo mecánico, pero el sonido por sí solo no identifica la pieza defectuosa. Evitar ciclos de encendido innecesarios y no abrir la unidad fuera de un entorno especializado. Confirmar si BIOS la detecta de forma estable y registrar comportamiento sin insistir. Si los datos son importantes, detener pruebas invasivas y escalar a recuperación profesional.', '["Referencia técnica interna; confirmar con el manual de servicio y esquema específicos de la placa"]', 'published', '2026-08-12T00:00:00.000Z', '2026-08-12T00:00:00.000Z');
INSERT OR IGNORE INTO knowledge_documents (id, title, tags, content, sources, status, created_at, updated_at) VALUES ('kb-nvme-detection', 'SSD y NVMe no detectados o intermitentes', '["ssd","nvme","storage-detection","bios-storage","pcie-storage"]', 'Separar detección física en BIOS/UEFI de visibilidad dentro del sistema operativo. Apagar y desconectar antes de reinstalar el módulo; revisar fijación, conector y compatibilidad de interfaz. Probar en otro puerto o adaptador compatible cuando sea seguro. Una unidad visible en BIOS pero ausente en Windows orienta a particionado, controlador o configuración; una desaparición también en BIOS requiere priorizar conexión, firmware de plataforma, alimentación y la propia unidad.', '["https://nvmexpress.org/specifications/"]', 'published', '2026-08-12T00:00:00.000Z', '2026-08-12T00:00:00.000Z');
INSERT OR IGNORE INTO knowledge_documents (id, title, tags, content, sources, status, created_at, updated_at) VALUES ('kb-memory-isolation', 'Aislamiento de fallas de RAM y ranuras', '["ram","memory-test","memory-module","memory-slot","post","bsod"]', 'Para reinicios, congelamientos, errores variables o ausencia de POST tras ampliar memoria, volver primero a la configuración conocida. Probar cada módulo por separado y luego cada ranura, manteniendo constantes las demás variables. Registrar ciclos completados y errores; una prueba rápida aprobada no descarta una falla intermitente. Verificar compatibilidad, asentamiento y parámetros de memoria. No atribuir automáticamente todos los pantallazos azules a RAM sin aislar módulo y ranura.', '["Referencia técnica interna; confirmar con el manual de servicio y esquema específicos de la placa"]', 'published', '2026-08-12T00:00:00.000Z', '2026-08-12T00:00:00.000Z');
INSERT OR IGNORE INTO knowledge_documents (id, title, tags, content, sources, status, created_at, updated_at) VALUES ('kb-windows-boot-recovery', 'Windows no inicia y entorno WinRE', '["windows-boot","winre","startup-repair","boot-loop","bcd","update"]', 'Confirmar primero que BIOS detecte la unidad y conservar datos importantes. WinRE ofrece Reparación de inicio, desinstalación de actualizaciones, Restaurar sistema y opciones de arranque. Registrar qué herramienta se ejecutó y su resultado; repetir Reparación de inicio sin nueva evidencia aporta poco. Si BitLocker está activo, solicitar la clave legítima. Separar corrupción de arranque de una unidad inestable mediante diagnóstico de almacenamiento y eventos registrados.', '["https://support.microsoft.com/en-us/windows/windows-recovery-environment-0eb14733-6301-41cb-8d26-06a12b42770b"]', 'published', '2026-08-12T00:00:00.000Z', '2026-08-12T00:00:00.000Z');
INSERT OR IGNORE INTO knowledge_documents (id, title, tags, content, sources, status, created_at, updated_at) VALUES ('kb-windows-system-files', 'Corrupción de archivos de sistema y filesystem', '["windows-corruption","dism","sfc","chkdsk","filesystem","slow-boot"]', 'DISM repara la imagen de Windows y SFC verifica archivos protegidos; registrar comandos y resultados completos. CHKDSK comprueba metadatos del filesystem, pero corregir errores implica escrituras y no sustituye un diagnóstico físico de la unidad. Antes de reparar, revisar salud del almacenamiento y respaldar datos cuando haya síntomas de hardware. Una corrupción reparable no demuestra por sí sola que el disco esté sano ni defectuoso.', '["https://support.microsoft.com/en-us/windows/windows-recovery-environment-0eb14733-6301-41cb-8d26-06a12b42770b"]', 'published', '2026-08-12T00:00:00.000Z', '2026-08-12T00:00:00.000Z');
INSERT OR IGNORE INTO knowledge_documents (id, title, tags, content, sources, status, created_at, updated_at) VALUES ('kb-thermal-throttling', 'Temperatura alta, throttling y apagado térmico', '["overheating","thermal-throttling","high-temperature","shutdown-load","performance-drop"]', 'Registrar temperatura, frecuencia, carga y tiempo hasta la caída de rendimiento o apagado. El throttling reduce frecuencia como protección y un apagado puede ocurrir si no alcanza para controlar la temperatura. Comparar con límites y comportamiento definidos por el OEM. No concluir pasta térmica seca sólo por una temperatura alta: comprobar ventiladores, flujo de aire, disipador, sensores, consumo y montaje antes de intervenir.', '["https://www.intel.com/content/www/us/en/support/articles/000088048/processors.html"]', 'published', '2026-08-12T00:00:00.000Z', '2026-08-12T00:00:00.000Z');
INSERT OR IGNORE INTO knowledge_documents (id, title, tags, content, sources, status, created_at, updated_at) VALUES ('kb-cooling-system', 'Ventiladores, disipador y flujo de aire', '["fan","airflow","dust","cooling","mechanical-noise","overheating"]', 'Inspeccionar entradas y salidas de aire, acumulación de polvo y operación de cada ventilador. Comparar RPM o flujo entre lados cuando el equipo tenga más de uno. Un ruido de roce puede venir de aspas, rodamiento, cable u objeto suelto. Limpiar con el equipo sin energía y evitar hacer girar el ventilador a velocidad excesiva. Tras intervenir, repetir la misma carga y registrar temperatura, frecuencia y ruido.', '["https://www.intel.com/content/www/us/en/support/articles/000088048/processors.html"]', 'published', '2026-08-12T00:00:00.000Z', '2026-08-12T00:00:00.000Z');
INSERT OR IGNORE INTO knowledge_documents (id, title, tags, content, sources, status, created_at, updated_at) VALUES ('kb-usb-port-basics', 'Puerto USB sin datos o alimentación', '["usb","usb-port","vbus","peripheral","port-power"]', 'Probar el mismo periférico y cable en otro puerto y un periférico conocido en el puerto afectado. Separar ausencia de VBUS de falla de enumeración de datos. Inspeccionar pines y daño mecánico sin energizar. Si falta alimentación, medir VBUS y revisar protección, switch de carga y señales de habilitación según esquema. No puentear fusibles ni protecciones; un corto en el periférico también puede desactivar el puerto.', '["https://www.usb.org/document-library/usb-power-delivery"]', 'published', '2026-08-12T00:00:00.000Z', '2026-08-12T00:00:00.000Z');
INSERT OR IGNORE INTO knowledge_documents (id, title, tags, content, sources, status, created_at, updated_at) VALUES ('kb-display-cable-hinge', 'Parpadeo de pantalla al mover la tapa', '["display-cable","hinge","flicker","internal-display","external-display"]', 'Si la imagen interna cambia al mover la tapa mientras el monitor externo permanece estable, registrar posiciones y reproducibilidad antes de desarmar. Con energía desconectada, inspeccionar cable eDP/LVDS, conectores, ruta por bisagras y puntos de pellizco. No asumir automáticamente panel o cable: una bisagra dañada, conector flojo o alimentación de backlight también puede producir intermitencia. Evitar flexionar repetidamente para no agravar el daño.', '["Referencia técnica interna; confirmar con el manual de servicio y esquema específicos de la placa"]', 'published', '2026-08-12T00:00:00.000Z', '2026-08-12T00:00:00.000Z');
INSERT OR IGNORE INTO knowledge_documents (id, title, tags, content, sources, status, created_at, updated_at) VALUES ('kb-liquid-damage-input', 'Teclado y entrada después de derrame', '["liquid-damage","keyboard","touchpad","corrosion","input-device"]', 'Después de un derrame, apagar, desconectar cargador y batería cuando sea seguro y evitar nuevas pruebas energizadas hasta inspeccionar. Documentar líquido, tiempo transcurrido y si fue encendido después. Comparar teclado o mouse externo para separar dispositivo interno de sistema. Inspeccionar flex, conectores y residuos; la ausencia de daño exterior no descarta corrosión. No garantizar recuperación sin revisar la placa y los módulos afectados.', '["https://www.dell.com/support/contents/en-us/article/product-support/self-support-knowledgebase/mouse-keyboard-touchpad/laptop-keyboard-not-working"]', 'published', '2026-08-12T00:00:00.000Z', '2026-08-12T00:00:00.000Z');
INSERT OR IGNORE INTO knowledge_documents (id, title, tags, content, sources, status, created_at, updated_at) VALUES ('kb-camera-detection', 'Cámara no detectada en Windows', '["camera","privacy-shutter","device-manager","driver","windows-update"]', 'Comprobar obturador o tecla física, permisos de privacidad y si la cámara aparece en Administrador de dispositivos. Probar la aplicación Cámara para separar un problema global de una aplicación concreta. Tras una actualización, revisar el controlador OEM y cambios de hardware; reinstalar o usar el controlador UVC genérico sólo cuando corresponda, porque puede perder funciones específicas. Si no aparece tampoco en firmware o diagnóstico OEM, investigar conexión y hardware.', '["https://support.microsoft.com/en-US/Windows/Hardware/Camera/camera-doesn-t-work-in-windows"]', 'published', '2026-08-12T00:00:00.000Z', '2026-08-12T00:00:00.000Z');
